#### REQ-IFR-INT-002-002: AWS API Gateway for Event Ingestion

**Status**: Recommended
**Rationale**: Serverless ingestion for external REST/HTTP events

**Requirements**:
- Configure API Gateway REST API with Kafka integration
- Use VPC Link to connect API Gateway to MSK
- Implement request validation and transformation
- Configure throttling limits per API key
- Enable access logging to CloudWatch

**Implementation**:
```hcl
# AWS API Gateway REST API for Event Ingestion
resource "aws_api_gateway_rest_api" "event_ingestion" {
  name        = "eaas-event-ingestion-${var.environment}"
  description = "API Gateway for external event ingestion to MSK"

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = merge(var.common_tags, {
    Name      = "eaas-event-ingestion-${var.environment}"
    Component = "gateway"
  })
}

# VPC Link for MSK connectivity
resource "aws_api_gateway_vpc_link" "msk" {
  name        = "eaas-msk-vpc-link-${var.environment}"
  description = "VPC Link to MSK cluster"
  target_arns = [aws_lb.msk_nlb.arn]

  tags = var.common_tags
}

# Network Load Balancer for MSK brokers
resource "aws_lb" "msk_nlb" {
  name               = "eaas-msk-nlb-${var.environment}"
  internal           = true
  load_balancer_type = "network"
  subnets            = var.private_subnet_ids

  enable_cross_zone_load_balancing = true

  tags = merge(var.common_tags, {
    Name = "eaas-msk-nlb-${var.environment}"
  })
}

resource "aws_lb_target_group" "msk_brokers" {
  name     = "eaas-msk-brokers-${var.environment}"
  port     = 9098  # IAM authentication port
  protocol = "TCP"
  vpc_id   = var.vpc_id

  health_check {
    enabled  = true
    protocol = "TCP"
    port     = 9098
  }

  tags = var.common_tags
}

# Event ingestion resource (/events)
resource "aws_api_gateway_resource" "events" {
  rest_api_id = aws_api_gateway_rest_api.event_ingestion.id
  parent_id   = aws_api_gateway_rest_api.event_ingestion.root_resource_id
  path_part   = "events"
}

# POST method for event submission
resource "aws_api_gateway_method" "post_event" {
  rest_api_id   = aws_api_gateway_rest_api.event_ingestion.id
  resource_id   = aws_api_gateway_resource.events.id
  http_method   = "POST"
  authorization = "AWS_IAM"

  request_validator_id = aws_api_gateway_request_validator.event_validator.id

  request_parameters = {
    "method.request.header.X-Event-Type" = true
    "method.request.header.X-Source-System" = true
  }
}

# Request validator
resource "aws_api_gateway_request_validator" "event_validator" {
  name                        = "event-validator"
  rest_api_id                 = aws_api_gateway_rest_api.event_ingestion.id
  validate_request_body       = true
  validate_request_parameters = true
}

# VPC Integration with Kafka producer Lambda
resource "aws_api_gateway_integration" "kafka_producer" {
  rest_api_id = aws_api_gateway_rest_api.event_ingestion.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.post_event.http_method

  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.kafka_producer.invoke_arn
  connection_type         = "VPC_LINK"
  connection_id           = aws_api_gateway_vpc_link.msk.id
}

# Lambda function for Kafka production
resource "aws_lambda_function" "kafka_producer" {
  filename      = "kafka_producer.zip"
  function_name = "eaas-api-kafka-producer-${var.environment}"
  role          = aws_iam_role.kafka_producer_lambda.arn
  handler       = "index.handler"
  runtime       = "python3.11"
  timeout       = 30
  memory_size   = 512

  vpc_config {
    subnet_ids         = var.private_subnet_ids
    security_group_ids = [aws_security_group.lambda_kafka_producer.id]
  }

  environment {
    variables = {
      KAFKA_BROKERS = module.msk_cluster.bootstrap_brokers_tls
      KAFKA_TOPIC   = "eaas.external.events"
    }
  }

  tags = var.common_tags
}

# API Gateway deployment
resource "aws_api_gateway_deployment" "event_ingestion" {
  rest_api_id = aws_api_gateway_rest_api.event_ingestion.id

  depends_on = [
    aws_api_gateway_integration.kafka_producer
  ]

  lifecycle {
    create_before_destroy = true
  }
}

# API Gateway stage
resource "aws_api_gateway_stage" "production" {
  deployment_id = aws_api_gateway_deployment.event_ingestion.id
  rest_api_id   = aws_api_gateway_rest_api.event_ingestion.id
  stage_name    = "production"

  # Access logging
  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_gateway_access.arn
    format = jsonencode({
      requestId      = "$context.requestId"
      ip             = "$context.identity.sourceIp"
      caller         = "$context.identity.caller"
      user           = "$context.identity.user"
      requestTime    = "$context.requestTime"
      httpMethod     = "$context.httpMethod"
      resourcePath   = "$context.resourcePath"
      status         = "$context.status"
      protocol       = "$context.protocol"
      responseLength = "$context.responseLength"
    })
  }

  # X-Ray tracing
  xray_tracing_enabled = true

  tags = var.common_tags
}

# Usage plan for throttling
resource "aws_api_gateway_usage_plan" "standard" {
  name        = "standard-tier-${var.environment}"
  description = "Standard tier with rate limiting"

  api_stages {
    api_id = aws_api_gateway_rest_api.event_ingestion.id
    stage  = aws_api_gateway_stage.production.stage_name
  }

  throttle_settings {
    burst_limit = 2000
    rate_limit  = 1000
  }

  quota_settings {
    limit  = 1000000
    period = "DAY"
  }
}

resource "aws_cloudwatch_log_group" "api_gateway_access" {
  name              = "/aws/apigateway/eaas-event-ingestion-${var.environment}"
  retention_in_days = 30

  tags = var.common_tags
}
```

