#### REQ-IFR-INT-002-003: Amazon EventBridge for SaaS Integration

**Status**: Recommended
**Rationale**: Native integration with SaaS providers (Salesforce, Zendesk, etc.)

**Requirements**:
- Configure EventBridge event bus for SaaS partner events
- Create rules to route events to MSK topics
- Implement schema validation using EventBridge Schema Registry
- Configure DLQ for failed event routing

**Implementation**:
```hcl
# Amazon EventBridge Custom Event Bus
resource "aws_cloudwatch_event_bus" "saas_integration" {
  name = "eaas-saas-integration-${var.environment}"

  tags = merge(var.common_tags, {
    Name      = "eaas-saas-integration-${var.environment}"
    Component = "eventbridge"
  })
}

# Event Bus Policy for SaaS Partners
resource "aws_cloudwatch_event_bus_policy" "saas_partners" {
  event_bus_name = aws_cloudwatch_event_bus.saas_integration.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSaaSPartnerPutEvents"
        Effect = "Allow"
        Principal = {
          AWS = var.saas_partner_account_ids
        }
        Action   = "events:PutEvents"
        Resource = aws_cloudwatch_event_bus.saas_integration.arn
      }
    ]
  })
}

# Salesforce events routing rule
resource "aws_cloudwatch_event_rule" "salesforce_events" {
  name           = "salesforce-to-msk-${var.environment}"
  description    = "Route Salesforce events to MSK"
  event_bus_name = aws_cloudwatch_event_bus.saas_integration.name

  event_pattern = jsonencode({
    source = ["aws.partner/salesforce.com"]
    detail-type = [
      "Account Change",
      "Opportunity Update",
      "Case Created"
    ]
  })

  tags = var.common_tags
}

# ServiceNow events routing rule
resource "aws_cloudwatch_event_rule" "servicenow_events" {
  name           = "servicenow-to-msk-${var.environment}"
  description    = "Route ServiceNow events to MSK"
  event_bus_name = aws_cloudwatch_event_bus.saas_integration.name

  event_pattern = jsonencode({
    source = ["servicenow.incident", "servicenow.change"]
    detail-type = [
      "Incident Created",
      "Incident Updated",
      "Change Request"
    ]
  })

  tags = var.common_tags
}

# API Destination for MSK (via Kafka REST Proxy)
resource "aws_cloudwatch_event_api_destination" "msk_rest_proxy" {
  name                             = "msk-rest-proxy-${var.environment}"
  description                      = "MSK Kafka REST Proxy endpoint"
  invocation_endpoint              = "https://kafka-rest-proxy.eaas.internal:8082/topics/eaas.saas.events"
  http_method                      = "POST"
  invocation_rate_limit_per_second = 300

  connection_arn = aws_cloudwatch_event_connection.msk_rest_proxy.arn
}

resource "aws_cloudwatch_event_connection" "msk_rest_proxy" {
  name        = "msk-rest-proxy-connection-${var.environment}"
  description = "Connection to MSK REST Proxy"

  authorization_type = "API_KEY"

  auth_parameters {
    api_key {
      key   = "X-API-Key"
      value = data.aws_secretsmanager_secret_version.rest_proxy_key.secret_string
    }
  }
}

# EventBridge Target - Salesforce to MSK
resource "aws_cloudwatch_event_target" "salesforce_to_msk" {
  rule           = aws_cloudwatch_event_rule.salesforce_events.name
  event_bus_name = aws_cloudwatch_event_bus.saas_integration.name
  arn            = aws_cloudwatch_event_api_destination.msk_rest_proxy.arn
  role_arn       = aws_iam_role.eventbridge_api_destination.arn

  http_target {
    path_parameter_values = []
    query_string_parameters = {}
    header_parameters = {
      "Content-Type" = "application/vnd.kafka.json.v2+json"
    }
  }

  input_transformer {
    input_paths = {
      detail     = "$.detail"
      source     = "$.source"
      detailType = "$.detail-type"
      time       = "$.time"
    }

    input_template = <<EOF
{
  "records": [
    {
      "value": {
        "source": <source>,
        "eventType": <detailType>,
        "timestamp": <time>,
        "payload": <detail>
      }
    }
  ]
}
EOF
  }

  retry_policy {
    maximum_retry_attempts       = 3
    maximum_event_age_in_seconds = 3600
  }

  dead_letter_config {
    arn = aws_sqs_queue.eventbridge_dlq.arn
  }
}

# EventBridge Target - ServiceNow to MSK
resource "aws_cloudwatch_event_target" "servicenow_to_msk" {
  rule           = aws_cloudwatch_event_rule.servicenow_events.name
  event_bus_name = aws_cloudwatch_event_bus.saas_integration.name
  arn            = aws_cloudwatch_event_api_destination.msk_rest_proxy.arn
  role_arn       = aws_iam_role.eventbridge_api_destination.arn

  http_target {
    header_parameters = {
      "Content-Type" = "application/vnd.kafka.json.v2+json"
    }
  }

  input_transformer {
    input_paths = {
      detail     = "$.detail"
      source     = "$.source"
      detailType = "$.detail-type"
      time       = "$.time"
    }

    input_template = <<EOF
{
  "records": [
    {
      "value": {
        "source": <source>,
        "eventType": <detailType>,
        "timestamp": <time>,
        "payload": <detail>
      }
    }
  ]
}
EOF
  }

  retry_policy {
    maximum_retry_attempts       = 3
    maximum_event_age_in_seconds = 3600
  }

  dead_letter_config {
    arn = aws_sqs_queue.eventbridge_dlq.arn
  }
}

# Dead Letter Queue for failed events
resource "aws_sqs_queue" "eventbridge_dlq" {
  name                      = "eaas-eventbridge-dlq-${var.environment}"
  message_retention_seconds = 1209600  # 14 days

  tags = var.common_tags
}

# IAM Role for EventBridge API Destinations
resource "aws_iam_role" "eventbridge_api_destination" {
  name = "eaas-eventbridge-api-dest-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
      }
    ]
  })

  tags = var.common_tags
}

resource "aws_iam_role_policy" "eventbridge_api_destination" {
  name = "invoke-api-destination"
  role = aws_iam_role.eventbridge_api_destination.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "events:InvokeApiDestination"
        ]
        Resource = aws_cloudwatch_event_api_destination.msk_rest_proxy.arn
      },
      {
        Effect = "Allow"
        Action = [
          "sqs:SendMessage"
        ]
        Resource = aws_sqs_queue.eventbridge_dlq.arn
      }
    ]
  })
}
```

