#### REQ-IFR-INT-002-004: WebSocket Gateway for Real-Time Events

**Status**: Recommended
**Rationale**: Support real-time bidirectional communication for IoT/mobile clients

**Requirements**:
- Configure API Gateway WebSocket API
- Implement connection management with DynamoDB
- Route WebSocket messages to Kafka topics
- Configure connection throttling and timeout

**Implementation**:
```hcl
# WebSocket API for Real-time Event Streaming
resource "aws_apigatewayv2_api" "websocket" {
  name                       = "eaas-websocket-${var.environment}"
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"

  tags = merge(var.common_tags, {
    Name      = "eaas-websocket-${var.environment}"
    Component = "websocket-gateway"
  })
}

# WebSocket authorizer (Lambda)
resource "aws_apigatewayv2_authorizer" "websocket_auth" {
  api_id           = aws_apigatewayv2_api.websocket.id
  authorizer_type  = "REQUEST"
  authorizer_uri   = aws_lambda_function.websocket_authorizer.invoke_arn
  identity_sources = ["route.request.querystring.token"]
  name             = "websocket-authorizer"
}

# $connect route
resource "aws_apigatewayv2_route" "connect" {
  api_id    = aws_apigatewayv2_api.websocket.id
  route_key = "$connect"

  authorization_type = "CUSTOM"
  authorizer_id      = aws_apigatewayv2_authorizer.websocket_auth.id

  target = "integrations/${aws_apigatewayv2_integration.connect.id}"
}

resource "aws_apigatewayv2_integration" "connect" {
  api_id           = aws_apigatewayv2_api.websocket.id
  integration_type = "AWS_PROXY"

  integration_uri        = aws_lambda_function.websocket_connect.invoke_arn
  integration_method     = "POST"
  content_handling_strategy = "CONVERT_TO_TEXT"
}

# $disconnect route
resource "aws_apigatewayv2_route" "disconnect" {
  api_id    = aws_apigatewayv2_api.websocket.id
  route_key = "$disconnect"

  target = "integrations/${aws_apigatewayv2_integration.disconnect.id}"
}

resource "aws_apigatewayv2_integration" "disconnect" {
  api_id           = aws_apigatewayv2_api.websocket.id
  integration_type = "AWS_PROXY"

  integration_uri    = aws_lambda_function.websocket_disconnect.invoke_arn
  integration_method = "POST"
}

# publishEvent route (custom action)
resource "aws_apigatewayv2_route" "publish_event" {
  api_id    = aws_apigatewayv2_api.websocket.id
  route_key = "publishEvent"

  target = "integrations/${aws_apigatewayv2_integration.publish_event.id}"
}

resource "aws_apigatewayv2_integration" "publish_event" {
  api_id           = aws_apigatewayv2_api.websocket.id
  integration_type = "AWS_PROXY"

  integration_uri    = aws_lambda_function.websocket_publish.invoke_arn
  integration_method = "POST"
}

# WebSocket stage
resource "aws_apigatewayv2_stage" "websocket_production" {
  api_id      = aws_apigatewayv2_api.websocket.id
  name        = "production"
  auto_deploy = true

  default_route_settings {
    throttling_burst_limit = 5000
    throttling_rate_limit  = 2000
    logging_level          = "INFO"
    data_trace_enabled     = true
  }

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.websocket_access.arn
    format = jsonencode({
      requestId      = "$context.requestId"
      ip             = "$context.identity.sourceIp"
      caller         = "$context.identity.caller"
      requestTime    = "$context.requestTime"
      eventType      = "$context.eventType"
      routeKey       = "$context.routeKey"
      status         = "$context.status"
      connectionId   = "$context.connectionId"
      integrationError = "$context.integrationErrorMessage"
    })
  }

  tags = var.common_tags
}

resource "aws_cloudwatch_log_group" "websocket_access" {
  name              = "/aws/apigatewayv2/eaas-websocket-${var.environment}"
  retention_in_days = 30

  tags = var.common_tags
}

# Lambda: WebSocket Connect Handler
resource "aws_lambda_function" "websocket_connect" {
  filename      = "websocket_connect.zip"
  function_name = "eaas-websocket-connect-${var.environment}"
  role          = aws_iam_role.websocket_lambda.arn
  handler       = "index.handler"
  runtime       = "python3.11"
  timeout       = 10

  vpc_config {
    subnet_ids         = var.private_subnet_ids
    security_group_ids = [aws_security_group.websocket_lambda.id]
  }

  environment {
    variables = {
      CONNECTION_TABLE = aws_dynamodb_table.websocket_connections.name
    }
  }

  tags = var.common_tags
}

# Lambda: WebSocket Disconnect Handler
resource "aws_lambda_function" "websocket_disconnect" {
  filename      = "websocket_disconnect.zip"
  function_name = "eaas-websocket-disconnect-${var.environment}"
  role          = aws_iam_role.websocket_lambda.arn
  handler       = "index.handler"
  runtime       = "python3.11"
  timeout       = 10

  vpc_config {
    subnet_ids         = var.private_subnet_ids
    security_group_ids = [aws_security_group.websocket_lambda.id]
  }

  environment {
    variables = {
      CONNECTION_TABLE = aws_dynamodb_table.websocket_connections.name
    }
  }

  tags = var.common_tags
}

# Lambda: WebSocket Publish Event Handler
resource "aws_lambda_function" "websocket_publish" {
  filename      = "websocket_publish.zip"
  function_name = "eaas-websocket-publish-${var.environment}"
  role          = aws_iam_role.websocket_lambda.arn
  handler       = "index.handler"
  runtime       = "python3.11"
  timeout       = 30
  memory_size   = 512

  vpc_config {
    subnet_ids         = var.private_subnet_ids
    security_group_ids = [aws_security_group.websocket_lambda.id]
  }

  environment {
    variables = {
      KAFKA_BROKERS = module.msk_cluster.bootstrap_brokers_tls
      KAFKA_TOPIC   = "eaas.websocket.events"
    }
  }

  tags = var.common_tags
}

# DynamoDB table for WebSocket connections
resource "aws_dynamodb_table" "websocket_connections" {
  name           = "eaas-websocket-connections-${var.environment}"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "connectionId"

  attribute {
    name = "connectionId"
    type = "S"
  }

  ttl {
    attribute_name = "ttl"
    enabled        = true
  }

  tags = var.common_tags
}
```

