#### REQ-IFR-INT-002-005: Gateway Authentication and Authorization

**Status**: Recommended
**Rationale**: Secure gateway access from external systems

**Requirements**:
- Implement OAuth 2.0 / JWT validation for API Gateway
- Configure mTLS for Kong Gateway
- Integrate with AWS IAM for internal clients
- Support API key authentication for legacy systems

**Implementation**:
```yaml
# Kong OAuth 2.0 Plugin Configuration
kong_oauth2_plugin:
  name: oauth2
  config:
    scopes:
      - event:publish
      - event:consume
      - gateway:admin
    mandatory_scope: true
    enable_authorization_code: true
    enable_client_credentials: true
    enable_implicit_grant: false
    enable_password_grant: false
    token_expiration: 3600
    auth_header_name: Authorization
    hide_credentials: true
    accept_http_if_already_terminated: false

# Kong mTLS Plugin Configuration
kong_mtls_plugin:
  name: mtls-auth
  config:
    ca_certificates:
      - ${ca_cert_id}
    skip_consumer_lookup: false
    allow_partial_chain: false
    authenticated_group_by: CN
    revocation_check_mode: IGNORE_CA_ERROR
    http_proxy_host: null
    http_proxy_port: null
    https_proxy_host: null
    https_proxy_port: null

# Kong ACL Plugin for Authorization
kong_acl_plugin:
  name: acl
  config:
    allow:
      - external-publishers
      - internal-services
      - admin-users
    deny: null
    hide_groups_header: true

---
# Terraform: API Gateway IAM Authorization
resource "aws_iam_policy" "api_gateway_invoke" {
  name        = "eaas-api-gateway-invoke-${var.environment}"
  description = "Policy for invoking event ingestion API"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "execute-api:Invoke"
        ]
        Resource = "${aws_api_gateway_rest_api.event_ingestion.execution_arn}/*/*/*"
      }
    ]
  })
}

# IAM Role for External Systems
resource "aws_iam_role" "external_publisher" {
  name = "eaas-external-publisher-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          AWS = var.external_system_account_ids
        }
        Condition = {
          StringEquals = {
            "sts:ExternalId" = var.external_publisher_external_id
          }
        }
      }
    ]
  })

  tags = var.common_tags
}

resource "aws_iam_role_policy_attachment" "external_publisher" {
  role       = aws_iam_role.external_publisher.name
  policy_arn = aws_iam_policy.api_gateway_invoke.arn
}

# API Gateway Resource Policy
resource "aws_api_gateway_rest_api_policy" "event_ingestion" {
  rest_api_id = aws_api_gateway_rest_api.event_ingestion.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.external_publisher.arn
        }
        Action   = "execute-api:Invoke"
        Resource = "${aws_api_gateway_rest_api.event_ingestion.execution_arn}/*"
      },
      {
        Effect = "Deny"
        Principal = "*"
        Action   = "execute-api:Invoke"
        Resource = "${aws_api_gateway_rest_api.event_ingestion.execution_arn}/*"
        Condition = {
          NotIpAddress = {
            "aws:SourceIp" = var.allowed_cidr_blocks
          }
        }
      }
    ]
  })
}

# ACM Certificate for mTLS
resource "aws_acm_certificate" "gateway_mtls" {
  domain_name       = "gateway.eaas.internal"
  validation_method = "DNS"

  subject_alternative_names = [
    "*.gateway.eaas.internal"
  ]

  tags = merge(var.common_tags, {
    Name = "eaas-gateway-mtls-${var.environment}"
  })

  lifecycle {
    create_before_destroy = true
  }
}
```

