[standards/infrastructure/integration/STD-INFRA-INT-002-protocol-translation-gateway.md#req-ifr-int-002-007-gateway-observability]

#### REQ-IFR-INT-002-007: Gateway Observability

**Status**: Recommended
**Rationale**: Monitor gateway performance and integration health

**Requirements**:
- Export gateway metrics to CloudWatch
- Enable access logs for all gateway APIs
- Implement distributed tracing with X-Ray
- Configure alerts for: error rate > 5%, latency > 1s, throttling rate > 10%

**Implementation**:
```hcl
# CloudWatch Log Groups
resource "aws_cloudwatch_log_group" "kong_proxy" {
  name              = "/aws/eks/kong/proxy-${var.environment}"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.logs.arn

  tags = var.common_tags
}

resource "aws_cloudwatch_log_group" "kong_admin" {
  name              = "/aws/eks/kong/admin-${var.environment}"
  retention_in_days = 90
  kms_key_id        = aws_kms_key.logs.arn

  tags = var.common_tags
}

# CloudWatch Metrics - API Gateway
resource "aws_cloudwatch_metric_alarm" "api_gateway_4xx" {
  alarm_name          = "api-gateway-4xx-errors-${var.environment}"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 2
  metric_name         = "4XXError"
  namespace           = "AWS/ApiGateway"
  period              = 300
  statistic           = "Sum"
  threshold           = 100
  alarm_description   = "API Gateway 4XX errors exceed threshold"
  alarm_actions       = [aws_sns_topic.gateway_alerts.arn]

  dimensions = {
    ApiName = aws_api_gateway_rest_api.event_ingestion.name
  }

  tags = var.common_tags
}

resource "aws_cloudwatch_metric_alarm" "api_gateway_5xx" {
  alarm_name          = "api-gateway-5xx-errors-${var.environment}"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 1
  metric_name         = "5XXError"
  namespace           = "AWS/ApiGateway"
  period              = 300
  statistic           = "Sum"
  threshold           = 10
  alarm_description   = "API Gateway 5XX errors exceed threshold"
  alarm_actions       = [aws_sns_topic.gateway_alerts.arn]
  treat_missing_data  = "notBreaching"

  dimensions = {
    ApiName = aws_api_gateway_rest_api.event_ingestion.name
  }

  tags = var.common_tags
}

resource "aws_cloudwatch_metric_alarm" "api_gateway_latency" {
  alarm_name          = "api-gateway-latency-${var.environment}"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 2
  metric_name         = "Latency"
  namespace           = "AWS/ApiGateway"
  period              = 300
  statistic           = "Average"
  threshold           = 3000  # 3 seconds
  alarm_description   = "API Gateway latency exceeds 3 seconds"
  alarm_actions       = [aws_sns_topic.gateway_alerts.arn]

  dimensions = {
    ApiName = aws_api_gateway_rest_api.event_ingestion.name
  }

  tags = var.common_tags
}

# CloudWatch Metrics - EventBridge
resource "aws_cloudwatch_metric_alarm" "eventbridge_failed_invocations" {
  alarm_name          = "eventbridge-failed-invocations-${var.environment}"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 1
  metric_name         = "FailedInvocations"
  namespace           = "AWS/Events"
  period              = 300
  statistic           = "Sum"
  threshold           = 5
  alarm_description   = "EventBridge failed invocations exceed threshold"
  alarm_actions       = [aws_sns_topic.gateway_alerts.arn]

  dimensions = {
    RuleName = aws_cloudwatch_event_rule.salesforce_events.name
  }

  tags = var.common_tags
}

# X-Ray Tracing for API Gateway
resource "aws_xray_sampling_rule" "api_gateway" {
  rule_name      = "eaas-api-gateway-${var.environment}"
  priority       = 1000
  version        = 1
  reservoir_size = 10
  fixed_rate     = 0.1
  url_path       = "*/events/*"
  host           = "*"
  http_method    = "POST"
  service_type   = "AWS::ApiGateway::Stage"
  service_name   = aws_api_gateway_stage.production.stage_name
  resource_arn   = "*"

  attributes = {
    Environment = var.environment
  }
}

# SNS Topic for Gateway Alerts
resource "aws_sns_topic" "gateway_alerts" {
  name              = "eaas-gateway-alerts-${var.environment}"
  kms_master_key_id = aws_kms_key.sns.id

  tags = var.common_tags
}

resource "aws_sns_topic_subscription" "gateway_pagerduty" {
  count     = var.enable_pagerduty ? 1 : 0
  topic_arn = aws_sns_topic.gateway_alerts.arn
  protocol  = "https"
  endpoint  = var.pagerduty_endpoint
}

# CloudWatch Dashboard
resource "aws_cloudwatch_dashboard" "gateway" {
  dashboard_name = "eaas-gateway-${var.environment}"

  dashboard_body = jsonencode({
    widgets = [
      {
        type = "metric"
        properties = {
          metrics = [
            ["AWS/ApiGateway", "Count", { stat = "Sum", label = "Total Requests" }],
            [".", "4XXError", { stat = "Sum", label = "4XX Errors" }],
            [".", "5XXError", { stat = "Sum", label = "5XX Errors" }]
          ]
          period = 300
          stat   = "Sum"
          region = var.aws_region
          title  = "API Gateway Requests and Errors"
        }
      },
      {
        type = "metric"
        properties = {
          metrics = [
            ["AWS/ApiGateway", "Latency", { stat = "Average", label = "Avg Latency" }],
            ["...", { stat = "Maximum", label = "Max Latency" }]
          ]
          period = 300
          region = var.aws_region
          title  = "API Gateway Latency"
          yAxis = {
            left = {
              label = "Milliseconds"
            }
          }
        }
      },
      {
        type = "metric"
        properties = {
          metrics = [
            ["AWS/Events", "Invocations", { stat = "Sum", label = "Total Invocations" }],
            [".", "FailedInvocations", { stat = "Sum", label = "Failed Invocations" }]
          ]
          period = 300
          region = var.aws_region
          title  = "EventBridge Invocations"
        }
      }
    ]
  })
}
```
